def opening_balances(apps,schema_editor):
    Profile=apps.get_model('characters','PlayerProfile')
    Entry=apps.get_model('characters','EconomicEntry')
    alias=schema_editor.connection.alias
    for profile in Profile.objects.using(alias).iterator():
        for resource,field in [('ore','ore_balance'),('shards','premium_balance')]:
            value=getattr(profile,field)
            if value:
                Entry.objects.using(alias).create(profile_id=profile.pk,resource=resource,amount=value,balance_after=value,category='opening',operation='ledger_installed',reference=uuid.uuid5(uuid.NAMESPACE_URL,f'ore-empire-opening:{profile.pk}:{resource}'))


